/// <summary>
/// Get From Slot substring based on type
/// </summary>
public static server str getFromSlot()
{
    str recId = SysComputedColumn::returnField(tablestr(METSlotTableView), dataEntityDataSourceStr(METSlotTableView, METSlotTable), fieldStr(METSlotTable, RecId));

    str expression = "SELECT CASE WHEN Type = 0 THEN COALESCE(SUBSTRING(FromSlot, 1, 3), '') WHEN Type = 1 THEN COALESCE(SUBSTRING(FromSlot, 1, 2), '') ELSE '' END AS FromSlotSubstring FROM METSlotTable where RECID =" + recId;

    return expression;
}

/// <summary>
/// Get To Slot substring based on type
/// </summary>
public static server str getToSlot()
{
    str recId = SysComputedColumn::returnField(tablestr(METSlotTableView), dataEntityDataSourceStr(METSlotTableView, METSlotTable), fieldStr(METSlotTable, RecId));

    str expression = "SELECT CASE WHEN Type = 0 THEN COALESCE(SUBSTRING(ToSlot, 1, 3), '') WHEN Type = 1 THEN COALESCE(SUBSTRING(ToSlot, 1, 2), '') ELSE '' END AS FromSlotSubstring FROM METSlotTable where RECID =" + recId;

    return expression;
}
